<?php
declare(strict_types=1);require_once __DIR__.'/../business/config/public_store_step23.php';$error=null;$order=null;$code=trim((string)($_POST['code']??''));$token=trim((string)($_POST['token']??''));if($_SERVER['REQUEST_METHOD']==='POST'&&$code!==''&&$token!==''){try{$pdo=ps23_db();$order=ps23_status($pdo,$code,$token);}catch(Throwable$e){$error=$e->getMessage();}}function st_label(string $s):string{return match($s){'submitted'=>'Submitted','reviewing'=>'Under Review','confirmed'=>'Confirmed','quote_ready'=>'Quote Ready','converted'=>'Converted to Sale','cancelled'=>'Cancelled',default=>ucwords(str_replace('_',' ',$s))};}?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Track Order Request - Healthcare Wellness Club</title><link rel="stylesheet" href="store.css"></head><body><header class="store-top"><div class="store-bar"><a class="store-brand" href="index.php"><img src="../img/logo.png"><span><strong>Healthcare Wellness Club</strong><small>Order Request Tracking</small></span></a><div class="store-actions"><a class="store-btn primary" href="index.php">Products</a></div></div></header><main class="store-shell"><section class="store-hero"><div class="store-kicker">PRIVATE TRACKING</div><h1>Track a product order request.</h1><p>Use your Order Request Code and private tracking key. The key is stored only as a one-way hash by the server, so keep your copy safe.</p></section><?php if($error):?><div class="notice bad"><?=ps23_h($error)?></div><?php endif;?><?php if(!$order):?><section class="card" style="max-width:720px;margin:16px auto"><form method="post"><label>Order Request Code<input class="store-input" name="code" value="<?=ps23_h($code)?>" placeholder="WEB-..." required></label><label style="display:block;margin-top:12px">Private Tracking Key<input class="store-input" name="token" value="<?=ps23_h($token)?>" autocomplete="off" required></label><button class="store-btn primary" style="width:100%;margin-top:12px">Track Request</button></form><div class="notice">Do not share your tracking key publicly.</div></section><?php else:?><section class="two-col" style="margin-top:16px"><article class="card"><div class="store-kicker">ORDER REQUEST</div><div class="order-code"><?=ps23_h($order['order_code'])?></div><?php if((string)($_POST['created']??'')==='1'):?><div class="notice">Request saved successfully. Save your Order Request Code and tracking key before leaving this page.</div><?php endif;?><div class="summary-line"><span>Status</span><strong><?=ps23_h(st_label((string)$order['order_status']))?></strong></div><div class="summary-line"><span>Payment</span><strong><?=ps23_h(ucwords(str_replace('_',' ',(string)$order['payment_status'])))?></strong></div><div class="summary-line"><span>Delivery</span><strong><?=ps23_h(ucwords(str_replace('_',' ',(string)$order['delivery_mode'])))?></strong></div><div class="summary-line"><span>MRP subtotal</span><strong><?=ps23_money($order['subtotal_mrp'])?></strong></div><div class="summary-line"><span>Delivery charge</span><strong><?=ps23_money($order['delivery_charge'])?></strong></div><div class="summary-line grand"><span>Estimated total</span><strong><?=ps23_money($order['estimated_total'])?></strong></div><div class="notice warn">Taxes are not calculated in this portal. Final amount is confirmed by the club.</div><h2>Products</h2><?php foreach($order['items'] as$i):?><div class="summary-line"><span><?=ps23_h($i['quantity'].' × '.$i['product_name_snapshot'])?></span><strong><?=ps23_money($i['line_mrp'])?></strong></div><?php endforeach;?></article><aside class="card"><h2>Progress</h2><div class="status-track"><?php foreach($order['events'] as$e):?><div class="status-item"><b><?=ps23_h($e['new_status']?st_label((string)$e['new_status']):ucwords(str_replace('_',' ',(string)$e['event_type'])))?></b><div class="meta"><?=ps23_h($e['created_at'])?></div></div><?php endforeach;?></div><div class="notice">Staff-only review notes are intentionally not shown on public tracking.</div></aside></section><?php endif;?></main><footer class="store-footer">Healthcare Wellness Club • Private request tracking</footer></body></html>